package android.view;public class View{Object tag;public View(android.content.Context c){}public void setTag(Object o){tag=o;}public Object getTag(){return tag;}public int getWidth(){return 1920;}public int getHeight(){return 720;}private static final java.util.concurrent.ScheduledExecutorService UI=java.util.concurrent.Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"fake-ui");t.setDaemon(true);return t;});public boolean post(Runnable r){UI.schedule(r,1,java.util.concurrent.TimeUnit.MILLISECONDS);return true;}}
